import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { RouterModule, ActivatedRoute } from '@angular/router';
import { ApiService } from '../../../core/services/api.service';

@Component({
  selector: 'app-article-detail',
  standalone: true,
  imports: [CommonModule, RouterModule],
  template: `
    <div *ngIf="article" class="fade-in">
      <div class="article-hero">
        <img [src]="article.imageUrl || 'https://picsum.photos/seed/' + article.slug + '/1200/500'" [alt]="article.title">
        <div class="hero-overlay">
          <div class="container">
            <span class="badge badge-primary">{{ article.category?.name }}</span>
            <h1>{{ article.title }}</h1>
            <div class="article-meta">
              <span><span class="material-icons">person</span> {{ article.author?.fullName }}</span>
              <span><span class="material-icons">calendar_today</span> {{ article.publishedAt | date:'dd/MM/yyyy' }}</span>
              <span><span class="material-icons">visibility</span> {{ article.viewCount }} lượt xem</span>
            </div>
          </div>
        </div>
      </div>
      <section class="section">
        <div class="container">
          <div class="article-layout">
            <article class="article-content">
              <div class="content" [innerHTML]="article.content"></div>
              <div class="article-tags" *ngIf="article.tags">
                <span class="tag" *ngFor="let t of getTags()">#{{ t }}</span>
              </div>
            </article>
          </div>
        </div>
      </section>
    </div>
    <div class="loading-spinner" *ngIf="!article"><div class="spinner"></div></div>
  `,
  styles: [`
    .article-hero { position: relative; height: 400px; overflow: hidden; img { width: 100%; height: 100%; object-fit: cover; } }
    .hero-overlay { position: absolute; bottom: 0; left: 0; right: 0; padding: 2rem; background: linear-gradient(transparent, rgba(0,0,0,0.7)); color: white; h1 { color: white; margin: 0.5rem 0; } }
    .article-meta { display: flex; gap: 1.5rem; font-size: 0.875rem; opacity: 0.9; span { display: flex; align-items: center; gap: 0.25rem; .material-icons { font-size: 1rem; } } }
    .article-layout { max-width: 800px; margin: 0 auto; }
    .article-content { font-size: 1.0625rem; line-height: 1.8; }
    .article-content p { margin-bottom: 1.25rem; }
    .article-content strong { color: var(--dark); }
    .article-tags { margin-top: 2rem; padding-top: 1.5rem; border-top: 1px solid #e2e8f0; display: flex; flex-wrap: wrap; gap: 0.5rem; }
    .tag { background: var(--light); color: var(--primary); padding: 0.25rem 0.75rem; border-radius: 50px; font-size: 0.875rem; font-weight: 500; }
  `]
})
export class ArticleDetailComponent implements OnInit {
  article: any = null;
  constructor(private api: ApiService, private route: ActivatedRoute) {}
  ngOnInit() {
    const slug = this.route.snapshot.paramMap.get('slug') || '';
    this.api.getArticle(slug).subscribe(data => { this.article = data; });
  }
  getTags(): string[] { return this.article?.tags?.split(',').map((t: string) => t.trim()) || []; }
}
